import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun next(): String {
        val result = StringBuilder()
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c != -1)
        while (c > 32 && c != -1) {
            result.append(c.toChar())
            c = readByte()
        }
        return result.toString()
    }

    fun nextLong(): Long = next().toLong()
}

fun main() {
    val scanner = FastScanner()
    val s = scanner.next()
    val len = s.length.toLong()
    val n = scanner.nextLong()

    fun check(a: Long): Boolean {
        var i = 1L
        while (i <= a - n) {
            if (s[(len - i).toInt()] != s[(len - i - a).toInt()]) {
                return false
            }
            i++
        }
        return true
    }

    val min = if (n > len) (len + n) / 2 else n
    val max = (len + n) / 2
    var ans = 0L
    var temp = 0L

    var i = 0L
    while (i < len) {
        var j = 1L
        while (j * 2 + i <= len) {
            var key = true
            var k = 1L
            while (k <= j) {
                if (s[(i + k - 1).toInt()] != s[(i + k + j - 1).toInt()]) {
                    key = false
                }
                k++
            }
            if (key && j > temp) {
                temp = j
            }
            j++
        }
        i++
    }

    i = max
    while (i >= min && ans == 0L) {
        if (check(i)) {
            ans = i
        }
        i--
    }

    if (min > ans) ans = min
    if (temp > ans) ans = temp

    print(2 * ans)
}

